public class LyricsSync
{
    private readonly Dictionary<Guid, List<(TimeSpan Time, string Text)>> _lyrics = new();

    public string? GetCurrentLine(Guid songId, TimeSpan currentTime)
    {
        if (!_lyrics.TryGetValue(songId, out var lines)) return null;
        return lines.LastOrDefault(l => l.Time <= currentTime).Text;
    }
}

